// Formats agent output for WhatsApp: strip metadata, remove em-dashes.
// A blank line in the model output means "send as separate bubbles" (only the opening message uses this).
const raw = $input.first().json.output || $input.first().json.message || '';

function clean(s) {
  return String(s)
    .replace(/\[STAGE:[^\]]+\](\s*\[REASON:[^\]]+\])?/g, '')
    .replace(/\u2014/g, ', ')
    .replace(/\u2013/g, ', ')
    .replace(/\s+-\s+/g, ', ')
    .replace(/,{2,}/g, ',')
    .replace(/,\s*,/g, ',')
    .trim();
}

const parts = String(raw).split(/\n\s*\n/).map(clean).filter(Boolean);

if (parts.length === 0) {
  return [{ json: { message: 'Desculpe, tive um problema técnico. Pode repetir sua mensagem? 😊' } }];
}

return parts.slice(0, 2).map((message) => ({ json: { message } }));

const weekdayNames = ['domingo','segunda','terça','quarta','quinta','sexta','sábado'];
const nowSP = $now.setZone('America/Sao_Paulo').startOf('day');

function isWeekend(dt) {
  const w = dt.weekday;
  return w === 6 || w === 7;
}

let firstBookable = nowSP.plus({ days: 2 });
while (isWeekend(firstBookable)) {
  firstBookable = firstBookable.plus({ days: 1 });
}
const first_bookable_date = firstBookable.toFormat('yyyy-MM-dd');

let table = [];
for (let i = 0; i <= 14; i++) {
  const dt = nowSP.plus({ days: i });
  const name = weekdayNames[dt.weekday % 7];
  const tags = [];
  if (i === 0) tags.push('hoje');
  if (isWeekend(dt)) tags.push('clínica fechada');
  if (dt.toFormat('yyyy-MM-dd') === first_bookable_date) tags.push('primeiro dia agendável');
  const tagStr = tags.length ? ` [${tags.join(', ')}]` : '';
  table.push(`${dt.toFormat('yyyy-MM-dd')} = ${name} (hoje+${i})${tagStr}`);
}
const date_lookup_table = table.join('\n');

let customer = {};
try { customer = $('Get a customer1').first().json || {}; } catch (e) {}

let patient_message = '';
try { patient_message = $('Merge1').first().json.text || ''; } catch (e) {}

let payment_status = 'NONE';
try {
  const pay = $('Buscar Status Pagamento').first().json;
  if (pay && pay.status) payment_status = pay.status;
} catch (e) {}

let selected_slot = '';
try {
  const slotItem = $('Get Selected Slot').first().json || {};
  selected_slot = slotItem.selected_slot || '';
} catch (e) {}

return [{
  json: {
    patient_message,
    customer_name: customer.nome || customer.name || '',
    date_lookup_table,
    first_bookable_date,
    payment_status,
    selected_slot,
  }
}];
